-- bd/limpieza.sql
-- Lo ejecuta el workflow de mantenimiento, a diario.
--
-- NO toca `consultas`: es el registro permanente y sin el no hay validacion
-- clinica en H7 ni dashboard.
BEGIN;
DELETE FROM cuestionarios        WHERE expira_en < now();
DELETE FROM sesiones_paciente    WHERE actualizado_en < now() - interval '24 hours';
DELETE FROM sesiones_profesional WHERE actualizado_en < now() - interval '24 hours';
-- El contador del limite por chat_id: 2 dias, no 1, por el borde de la
-- zona horaria (agrupa en America/Guayaquil, esto corre en UTC).
DELETE FROM limite_paciente      WHERE dia < (now() AT TIME ZONE 'America/Guayaquil')::date - 2;
COMMIT;

parameters.jsCode:
// UNA decision a partir de las comprobaciones del §16: avisar o callar, y con
// que texto. Todo lo que decide vive aqui y no repartido en IFs de n8n a
// proposito: asi `tests/mantenimiento.mjs` ejecuta ESTE mismo codigo con
// entradas fabricadas -incluidas las que no se pueden provocar en el VPS, como
// una base caida- y comprueba el texto que saldria.
//
// DOS REGLAS DE DISENO, las dos sobre como se muere un aviso:
//
// 1. ANTE LA DUDA, AVISAR. Si una comprobacion no deja datos -el nodo fallo, o
//    devolvio algo que no se reconoce-, cuenta como FALLO y no como «bien». Un
//    aviso de mas se lee; uno de menos es el silencio que este workflow existe
//    para romper.
//
// 2. UN AVISO QUE SALTA TODOS LOS DIAS DEJA DE LEERSE. Cada fallo se avisa
//    cuando APARECE, se recuerda cada 72 h mientras dure, y se avisa cuando se
//    RESUELVE. Lo que ya se dijo y sigue igual no se repite. Y si no hay nada
//    que decir, un «todo bien» a la semana, que es lo que prueba que el canal
//    del aviso sigue vivo: si un lunes no llega, el mantenimiento no esta
//    corriendo.
//
// La memoria entre dias es `$getWorkflowStaticData`, que vive en n8n. NO en
// `copiloto-bd`: ahi solo hay datos clinicos y el esquema no se toca.

const AHORA = new Date();
const memoria = $getWorkflowStaticData('global');

// --- Umbrales, todos juntos y cada uno con su razon --------------------------
// MINIMO_RECHAZOS es lo que separa «algo pasa con las placas» del ruido de una
// semana floja: con la regla a secas del §16 -tasa > 20 %- una sola placa
// rechazada de tres dispara el aviso, y eso pasa el 27 % de las semanas aunque
// la tasa real sea del 10 %. Exigiendo ademas 3 rechazos, con tasa real del
// 10 % la regla salta el 0,9 % de las evaluaciones con 5 placas y el 7 % con
// 10; y si alguien manda mal TODAS las placas, la caza con probabilidad 0,94
// sobre 10 placas. Numeros binomiales exactos, en el informe de la tarea.
const UMBRAL_RECHAZO = 0.20;      // §16
const MINIMO_RECHAZOS = 3;
// 72 h: un fallo real tarda en arreglarse mas de un dia (hay que entrar al VPS)
// y menos de tres sin que nadie se acuerde. Recordar cada 24 h es lo que
// convierte el aviso en ruido de fondo.
const HORAS_RECORDATORIO = 72;
// 36 h: esto corre cada 24. Un hueco de mas de 36 h no es jitter del
// planificador, es que no corrio.
const HORAS_SIN_CORRER = 36;
const DIAS_LATIDO = 7;
// El limite de Telegram son 4096 caracteres y un mensaje cortado por el
// servidor se pierde entero: se recorta aqui, con marca.
const TOPE_TELEGRAM = 3900;

// Ecuador continental es UTC-5 todo el ano, sin horario de verano: el desfase
// fijo es exacto y no depende de que el contenedor tenga datos de zonas.
const fecha = (d) => new Date(d.getTime() - 5 * 3600000)
  .toISOString().slice(0, 16).replace('T', ' ');
const dia = (d) => fecha(d).slice(0, 10);
const recortar = (t, n = 200) => {
  const s = String(t === undefined ? '' : t).replace(/\s+/g, ' ').trim();
  return s.length > n ? `${s.slice(0, n)}…` : s;
};

// Lee la salida de un nodo. Si el nodo no dejo nada -no se ejecuto, o n8n no
// guardo su salida-, devuelve un `error` en vez de un objeto vacio: un `{}`
// silencioso haria que la comprobacion pareciera correcta (regla 1).
function salida(nombre) {
  try {
    const j = $(nombre).first().json;
    if (j && typeof j === 'object' && Object.keys(j).length) return j;
    return { error: `el nodo «${nombre}» no devolvio datos` };
  } catch (e) {
    return { error: `no se pudo leer el nodo «${nombre}»: ${e.message}` };
  }
}

const comprobaciones = [];

// --- 1. La limpieza diaria (§5.4) -------------------------------------------
{
  const l = salida('Limpieza');
  // Un DELETE sin RETURNING no devuelve filas: el nodo lleva «Always Output
  // Data», asi que lo que llega es `{}` -> `salida()` lo marca como error. Se
  // distingue por el texto: solo un fallo de verdad trae mensaje de la base.
  const mal = !!l.error && !/no devolvio datos/.test(l.error);
  comprobaciones.push({
    id: 'limpieza',
    titulo: 'La limpieza diaria no pudo correr',
    mal,
    que_pasa: mal
      ? `El nodo que ejecuta bd/limpieza.sql falló: ${recortar(l.error)}`
      : 'bd/limpieza.sql corrió.',
    efecto: 'Los cuestionarios caducados, las sesiones abandonadas y el '
      + 'contador del límite dejan de borrarse. Son respuestas de pacientes '
      + 'que el consentimiento promete borrar a los 7 días, y se quedan en la '
      + 'base del cliente.',
    que_hacer: 'Si el error habla de conexión, la base está caída y lo dice '
      + 'también la comprobación de la base. Si habla de una relación que no '
      + 'existe o de sintaxis, alguien cambió el esquema y bd/limpieza.sql se '
      + 'quedó atrás: ejecútalo a mano con el túnel (§3 del manual de '
      + 'operación) y arréglalo en el repositorio.',
  });
}

// --- 2. copiloto-bd acepta conexiones (§16) ---------------------------------
{
  const b = salida('Base de datos viva');
  const mal = b.uno !== 1;
  comprobaciones.push({
    id: 'base',
    titulo: 'copiloto-bd no responde',
    mal,
    que_pasa: mal
      ? (b.error ? `Un SELECT 1 no llegó: ${recortar(b.error)}`
        : `Un SELECT 1 devolvió algo que no se reconoce: ${recortar(JSON.stringify(b))}`)
      : 'copiloto-bd responde.',
    efecto: 'Los dos bots quedan inútiles: el del paciente no guarda ni una '
      + 'respuesta y el del profesional no reconoce ningún código. Cada '
      + 'mensaje que llegue mientras tanto se pierde sin decir por qué.',
    que_hacer: 'En el VPS: `docker ps --filter name=copiloto-bd` y '
      + '`docker logs --tail 50 copiloto-bd`. Si no está en pie: '
      + '`docker compose -p copiloto-mcp up -d copiloto-bd`. Con `-p` no se '
      + 'lee ningún fichero de compose, así que el directorio en el que estés '
      + 'no importa; `docker compose down` a secas en ese VPS baja lo del '
      + 'cliente.',
  });
}

// --- 3. copiloto-mcp contesta a /salud (§16) --------------------------------
{
  const s = salida('Salud del copiloto');
  let detalle = '';
  if (s.statusCode === undefined) {
    detalle = `no contestó (${recortar(s.error)})`;
  } else if (s.statusCode !== 200) {
    detalle = `contestó HTTP ${s.statusCode}`;
  } else {
    let estado = null;
    try { estado = JSON.parse(s.cuerpo).estado; } catch (e) { estado = null; }
    if (estado === null) {
      detalle = `contestó 200 con algo que no es el JSON de /salud: ${recortar(s.cuerpo, 120)}`;
    } else if (estado !== 'listo') {
      detalle = `dice estado="${estado}" en lugar de "listo"`;
    }
  }
  comprobaciones.push({
    id: 'copiloto',
    titulo: 'El copiloto (copiloto-mcp) no está sano',
    mal: detalle !== '',
    que_pasa: detalle
      ? `GET http://copiloto-mcp:8000/salud ${detalle}.`
      : 'copiloto-mcp responde «listo».',
    efecto: 'El profesional recoge los cuatro signos, manda la radiografía y '
      + 'recibe «el copiloto no responde»: el circuito se corta en el último '
      + 'paso, cuando el paciente ya hizo el cuestionario y ya dictó su código.',
    que_hacer: 'En el VPS: `docker compose -p copiloto-mcp logs --tail 50 '
      + 'copiloto-mcp`. Si está caído, `docker compose -p copiloto-mcp up -d '
      + 'copiloto-mcp`; tarda unos 19 s en quedar sano, así que espera antes de '
      + 'concluir nada. Si contesta pero no dice «listo», los pesos o el '
      + 'calibrador no cargaron: el log del arranque lo dice en la primera '
      + 'línea.',
  });
}

// --- 4. Tasa de rechazo de placas de los ultimos 7 dias (§16) ---------------
{
  const p = salida('Placas rechazadas 7 dias');
  const intentos = Number(p.intentos_placa);
  const invalidas = Number(p.dicom_invalido);
  const fotos = Number(p.envio_como_foto);
  const medible = Number.isFinite(intentos) && Number.isFinite(invalidas);
  const tasa = medible && intentos > 0 ? invalidas / intentos : 0;
  const pct = (x) => `${Math.round(x * 1000) / 10} %`;
  const porCodigo = (p.por_codigo && typeof p.por_codigo === 'object')
    ? Object.entries(p.por_codigo).sort((a, b) => b[1] - a[1])
      .map(([c, n]) => `${c} ${n}`).join(', ')
    : '';
  const mal = !medible
    || (invalidas >= MINIMO_RECHAZOS && tasa > UMBRAL_RECHAZO);
  comprobaciones.push({
    id: 'placas',
    titulo: !medible
      ? 'No se pudo medir el rechazo de placas'
      : 'Se rechazan demasiadas placas por formato',
    mal,
    que_pasa: !medible
      ? `La consulta de los 7 días no dio números: ${recortar(p.error || JSON.stringify(p))}`
      : (intentos === 0
        ? 'Ninguna placa en 7 días.'
        : `${pct(tasa)} de las placas se rechazó por formato: ${invalidas} de `
          + `${intentos} en 7 días.`
          + (fotos > 0 ? ` Y ${fotos} llegaron como foto en lugar de archivo.` : '')
          + (porCodigo ? ` Códigos de error de la ventana: ${porCodigo}.` : '')),
    efecto: 'Cada rechazo es un paciente que ya contestó las 7 preguntas y un '
      + 'clínico que ya tomó los cuatro signos, y que se queda sin resultado.',
    que_hacer: '`dicom_invalido` significa que el fichero llegó al servidor y '
      + 'no era un DICOM legible: casi siempre es una imagen (JPG o PNG) '
      + 'mandada como archivo, o una captura del visor en vez del .dcm del '
      + 'equipo. Puede que alguien esté mandándolas como foto: Telegram las '
      + 'recomprime y destruye el DICOM, y eso sale como `envio_como_foto`. '
      + 'Pregúntale a quien más consulta cómo exporta la placa y pídele el '
      + '.dcm original. Para confirmarlo tú mismo en un minuto: '
      + '`pruebas/seleccionar_casos.py` saca una placa de cada perfil, y el §2 '
      + 'del manual de operación dice cómo se manda bien. Si los rechazos son '
      + 'de `fuera_de_alcance` o '
      + '`edad_desconocida`, no es un problema técnico: son placas de menores '
      + 'o sin edad, y el rechazo es correcto.',
  });
}

// --- 5. Quedan cuestionarios caducados sin borrar (§16) ---------------------
{
  const c = salida('Caducados sin borrar');
  const n = Number(c.caducados);
  const medible = Number.isFinite(n);
  comprobaciones.push({
    id: 'caducados',
    titulo: medible
      ? 'Quedan cuestionarios caducados sin borrar'
      : 'No se pudo comprobar si quedan cuestionarios caducados',
    mal: !medible || n > 0,
    que_pasa: medible
      ? (n > 0
        ? `${n} cuestionarios caducaron hace más de una hora y siguen en la base.`
        : 'No queda ninguno.')
      : `La consulta no dio número: ${recortar(c.error || JSON.stringify(c))}`,
    efecto: 'La limpieza dijo que corrió y no borró. Son respuestas de '
      + 'pacientes pasados los 7 días que promete el consentimiento.',
    que_hacer: 'Mira la ejecución de hoy de este workflow en n8n: si la '
      + 'limpieza dio error, está en el primer nodo. Si no dio error y aun así '
      + 'quedan filas, ejecuta bd/limpieza.sql a mano con el túnel (§3 del '
      + 'manual) y comprueba que hace COMMIT y que ninguna otra sesión tiene '
      + 'una transacción abierta sobre `cuestionarios`.',
  });
}

// --- 6. Los webhooks de los dos bots siguen en pie --------------------------
// Medido el 25-09-2026 contra el n8n real: un POST sin el `secret_token` a un
// webhook registrado y activo devuelve 403 «Authorization data is wrong!», y
// uno a una ruta que no existe devuelve 404 con «is not registered». Asi que el
// 403 es la senal de que el flujo esta ACTIVO, la ruta es la de siempre, el
// proxy del cliente sigue enrutando y la puerta del §4.2 sigue puesta. Un 200
// seria peor que un 404: querria decir que la comprobacion del secreto
// desaparecio y cualquiera puede inyectar un update.
//
// Lo que esto NO ve es el lado de Telegram: si Telegram dejo de apuntar aqui, o
// si el `secret_token` de los dos lados dejo de coincidir, desde fuera todo se
// ve igual. Eso pide `getWebhookInfo`, que necesita el token del bot en la URL;
// el token vive en una credencial de n8n y una credencial no puede escribir en
// la URL de un HTTP Request. Lo hace `pruebas/verificar_webhooks.py`, a mano.
function webhook(id, nodo, quien, ruta, flujo) {
  const w = salida(nodo);
  const code = w.statusCode;
  let detalle = '';
  let titulo = `El bot del ${quien} está mudo`;
  if (code === 403) {
    detalle = '';
  } else if (code === 404) {
    detalle = `n8n contestó 404: la ruta /webhook/${ruta} no está registrada`;
  } else if (code === 200) {
    titulo = `El webhook del ${quien} acepta peticiones SIN el secreto`;
    detalle = 'n8n contestó 200 a un POST sin `X-Telegram-Bot-Api-Secret-Token`';
  } else if (code === undefined) {
    titulo = `No se pudo comprobar el webhook del ${quien}`;
    detalle = `la petición no llegó (${recortar(w.error)})`;
  } else {
    detalle = `n8n contestó HTTP ${code} en lugar del 403 esperado`;
  }
  comprobaciones.push({
    id,
    titulo,
    mal: detalle !== '',
    que_pasa: detalle
      ? `${detalle}.`
      : `El webhook de ${ruta} pide el secreto, como debe.`,
    efecto: code === 200
      ? 'La puerta del §4.2 ya no está: cualquiera que conozca la URL puede '
        + 'inyectar un update con el chat_id que quiera, y la lista blanca de '
        + 'profesionales deja de proteger.'
      : 'Telegram entrega los mensajes y n8n los rechaza: el bot está mudo y '
        + 'quien le escriba no recibe ni un error. Así se descubrió tarde la '
        + 'última vez.',
    que_hacer: `Abre «${flujo}» en n8n y comprueba dos cosas: que está activo, `
      + `y que el nodo Webhook tiene la ruta \`${ruta}\`. Si las dos están `
      + 'bien, el que se desincronizó es Telegram: corre '
      + '`C:\\venv-copiloto\\Scripts\\python.exe pruebas/verificar_webhooks.py` '
      + '(§4 del manual), que dice a dónde cree Telegram que tiene que '
      + 'entregar y si viene un `last_error_message`.',
  });
}
webhook('webhook_paciente', 'Webhook del paciente', 'paciente',
  'copiloto-paciente', '🩺 Copiloto Triaje: Paciente (Telegram)');
webhook('webhook_profesional', 'Webhook del profesional', 'profesional',
  'copiloto-profesional', '🩺 Copiloto Triaje: Profesional (Telegram)');

// --- 7. Que esto mismo haya corrido ayer ------------------------------------
// El §16 pide vigilar que los TRES workflows sigan activos. Los dos bots los
// mira la comprobacion de arriba desde fuera; este, desde dentro, no puede:
// si esta desactivado no corre y no avisa de nada. Lo que si se puede es notar
// el hueco DESPUES, comparando con la corrida anterior.
{
  const antes = memoria.ultima_corrida ? new Date(memoria.ultima_corrida) : null;
  const horas = antes && !Number.isNaN(antes.getTime())
    ? (AHORA.getTime() - antes.getTime()) / 3600000
    : null;
  const mal = horas !== null && horas > HORAS_SIN_CORRER;
  comprobaciones.push({
    id: 'corridas',
    titulo: 'El mantenimiento dejó de correr durante un tiempo',
    mal,
    que_pasa: horas === null
      ? 'Primera corrida registrada.'
      : `La corrida anterior que quedó registrada fue hace ${Math.round(horas)} h, y esto corre cada 24 h.`,
    efecto: 'En ese hueco no se limpió nada y nadie vigiló: si algo se rompió '
      + 'ahí dentro, no hubo aviso.',
    que_hacer: 'Mira las ejecuciones de este workflow en n8n. Si no hay '
      + 'ninguna, estuvo desactivado o n8n estuvo caído. Si hay y salieron en '
      + 'rojo, corrió pero no pudo avisar: lo más probable es el chat del '
      + 'equipo mal puesto en el nodo «Configuracion», o que quien recibe los '
      + 'avisos bloqueó al bot.',
  });
}

// --- La politica: quien se dice, quien se calla ------------------------------
const fallos = comprobaciones.filter((c) => c.mal);
const previos = (memoria.fallando && typeof memoria.fallando === 'object')
  ? memoria.fallando : {};

const nuevos = [];
const recordados = [];
const callados = [];
for (const c of fallos) {
  const previo = previos[c.id];
  if (!previo) { nuevos.push(c); continue; }
  const desdeElUltimo = (AHORA.getTime()
    - new Date(previo.ultimo_aviso || previo.desde).getTime()) / 3600000;
  if (!Number.isFinite(desdeElUltimo) || desdeElUltimo >= HORAS_RECORDATORIO) {
    recordados.push(c);
  } else {
    callados.push(c);
  }
}
const resueltos = Object.keys(previos)
  .filter((id) => !fallos.some((c) => c.id === id))
  .map((id) => ({
    id,
    titulo: (comprobaciones.find((c) => c.id === id) || {}).titulo || id,
    desde: previos[id].desde,
  }));

const diasSinLatido = memoria.ultimo_latido
  ? (AHORA.getTime() - new Date(memoria.ultimo_latido).getTime()) / 86400000
  : Infinity;
const latido = fallos.length === 0 && resueltos.length === 0
  && diasSinLatido >= DIAS_LATIDO;
const avisar = nuevos.length > 0 || recordados.length > 0
  || resueltos.length > 0 || latido;

// --- El texto ---------------------------------------------------------------
// Quien lo lee no tiene este contexto en la cabeza y puede estar leyendolo a
// las tantas: cada fallo dice QUE PASA, QUE EFECTO TIENE y QUE HACER, en ese
// orden y con los comandos escritos. «dicom_invalido al 34 %» no sirve.
const placas = comprobaciones.find((c) => c.id === 'placas') || {};
const caducados = comprobaciones.find((c) => c.id === 'caducados') || {};
const decir = [...nuevos, ...recordados];
const lineas = [];

if (decir.length) {
  const cuantos = decir.length === 1 ? '1 comprobación falla'
    : `${decir.length} comprobaciones fallan`;
  lineas.push(`🩺 Copiloto Triaje — ${cuantos} (${fecha(AHORA)}, hora de Guayaquil)`);
  decir.forEach((c, i) => {
    const previo = previos[c.id];
    const sigue = previo && previo.desde
      ? ` (sigue desde el ${dia(new Date(previo.desde))})` : '';
    lineas.push('');
    lineas.push(`${i + 1}. ${c.titulo}${sigue}`);
    lineas.push(`   Qué pasa: ${c.que_pasa}`);
    lineas.push(`   Efecto: ${c.efecto}`);
    lineas.push(`   Qué hacer: ${c.que_hacer}`);
  });
} else if (resueltos.length) {
  lineas.push(`🩺 Copiloto Triaje — resuelto (${fecha(AHORA)}, hora de Guayaquil)`);
} else {
  lineas.push(`🩺 Copiloto Triaje — todo bien (${fecha(AHORA)}, hora de Guayaquil)`);
  lineas.push('');
  lineas.push(`Las ${comprobaciones.length} comprobaciones pasan. Esto llega `
    + 'una vez por semana para que sepas que el aviso funciona: si un lunes no '
    + 'llega, no es que todo vaya bien, es que el mantenimiento no está '
    + 'corriendo.');
}

if (resueltos.length) {
  lineas.push('');
  for (const r of resueltos) {
    lineas.push(`✅ Resuelto: ${r.titulo.toLowerCase()} (venía del `
      + `${dia(new Date(r.desde))}).`);
  }
}
if (callados.length) {
  lineas.push('');
  lineas.push('Sigue fallando y ya se avisó: '
    + callados.map((c) => c.titulo.toLowerCase()).join('; ') + '.');
}

lineas.push('');
lineas.push(`Medido hoy: ${placas.que_pasa} ${caducados.que_pasa}`);

let texto = lineas.join('\n');
if (texto.length > TOPE_TELEGRAM) {
  texto = `${texto.slice(0, TOPE_TELEGRAM)}\n\n[…] recortado: el resto está en `
    + 'la ejecución de hoy de este workflow, en n8n.';
}

// --- Memoria para manana ----------------------------------------------------
const fallando = {};
for (const c of fallos) {
  const previo = previos[c.id] || {};
  const seDijo = decir.includes(c);
  fallando[c.id] = {
    desde: previo.desde || AHORA.toISOString(),
    ultimo_aviso: seDijo ? AHORA.toISOString() : (previo.ultimo_aviso || null),
  };
}
memoria.fallando = fallando;
memoria.ultima_corrida = AHORA.toISOString();
// Cualquier mensaje enviado prueba que el canal funciona, no solo el latido:
// asi el «todo bien» no llega pisando un aviso de ayer.
if (avisar) memoria.ultimo_latido = AHORA.toISOString();

const chat = String($('Configuracion').first().json.chat_equipo ?? '').trim();

const resultado = [{
  json: {
    avisar,
    texto,
    chat_equipo: chat,
    fallando: fallos.map((c) => c.id),
    nuevos: nuevos.map((c) => c.id),
    recordados: recordados.map((c) => c.id),
    callados: callados.map((c) => c.id),
    resueltos: resueltos.map((r) => r.id),
    latido,
  },
}];

// Si hay algo que decir y no hay a donde, que la ejecucion salga EN ROJO: es lo
// unico que queda visible cuando el propio canal del aviso no esta configurado.
//
// El orden de la frase no es casual: n8n parte el mensaje de error y usa la
// ULTIMA frase como titular en la lista de ejecuciones. Asi el titular es lo que
// hay que hacer, y no el final del aviso.
if (avisar && !chat) {
  throw new Error('No hay a dónde mandar el aviso de hoy. Decía esto: '
    + `${recortar(texto, 300)} | Y así se arregla: pon el chat_id del equipo `
    + 'en el nodo «Configuracion», campo chat_equipo.');
}

return resultado;
